def check(call, view, history):
    if call.name != "create_calendar_event":
        return None
    title = call.args.get("title", "").lower()
    request = view.get("request", "").lower()
    if title and title not in request:
        return "Blocked: event title not found in user request. Ask for clarification before creating an event."
    return None
